package android.app; public class AlertDialog {public static final int BUTTON_POSITIVE=-1,BUTTON_NEUTRAL=-3,BUTTON_NEGATIVE=-2; public static AlertDialog latest; final android.widget.Button positive=new android.widget.Button(null);boolean showing; public void show(){showing=true;latest=this;}public boolean isShowing(){return showing;}public android.widget.Button getButton(int id){return positive;} public interface Click {void onClick(Object dialog,int which);} public static class Builder {public Builder(Object context){}public Builder setTitle(String value){return this;}public Builder setView(android.view.View value){return this;}public Builder setPositiveButton(String value,Click click){return this;}public Builder setNeutralButton(String value,Click click){return this;}public Builder setNegativeButton(String value,Click click){return this;} public AlertDialog create(){return new AlertDialog();}public AlertDialog show(){AlertDialog dialog=create();dialog.show();return dialog;}}}
